<script setup lang="ts">import type {Run} from '../types/domain';import {hasConstraints} from '../types/domain';import StatusBadge from './common/StatusBadge.vue';import {date,number} from '../utils/format';defineProps<{runs:Run[]}>();</script><template><div class="table-wrap"><table><thead><tr><th>研究名称</th><th>状态</th><th>候选K</th><th>轮廓系数</th><th>建立时间</th><th></th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td><strong>{{run.name}}</strong><small>{{run.features.length}} 个特征 · SEED 42<template v-if="hasConstraints(run)"> · 含分群约束</template></small></td><td><StatusBadge :status="run.status"/><small v-if="run.status==='failed'&&run.error" class="fail-reason" :title="run.error">{{run.error}}</small></td><td>{{run.k_min}}—{{run.k_max}}</td><td>{{number(run.result.silhouette,3)}}</td><td>{{date(run.created_at)}}</td><td><RouterLink :to="'/segments?run='+run.id">查看研究 ↗</RouterLink></td></tr></tbody></table></div></template>
